from pathlib import Path
import base64
import gzip

FILES = {
    "app/src/main/java/com/officerj/autospa/giveaway/MainActivity.kt": "",
    "app/src/main/java/com/officerj/autospa/giveaway/DocumentEntryImporter.kt": "",
    "app/src/main/java/com/officerj/autospa/giveaway/AppSettings.kt": "",
    "app/build.gradle.kts": "",
    "CHANGES_v1.1.9.txt": ""
}

for rel, payload in FILES.items():
    path = Path(rel)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))

for rel in [
    "app/src/main/java/com/officerj/autospa/giveaway/EngagementModels.kt",
    "app/src/main/java/com/officerj/autospa/giveaway/EngagementStore.kt",
    "app/src/main/java/com/officerj/autospa/giveaway/MetaEngagementClient.kt",
]:
    Path(rel).unlink(missing_ok=True)

# Remove the one-shot migration files from the resulting source tree.
Path("scripts/apply-v1.1.9-cleanup.py").unlink(missing_ok=True)
Path(".github/workflows/apply-v1.1.9.yml").unlink(missing_ok=True)
